ltmp0:			dc.l 0
			even
ntc_csp:	dc.l 0					; the real stack (set at start)
ntc_ip:		dc.l 0					; the thread position while on the real stack
ntc_ivar:	dc.l 0					; input / inkey / ticks: dest var
ntc_sptr:	dc.l 0					; printbuf: text pointer
ntc_numbuf:	ds.b 16					; printint / long print: digits
			even
ntc_ia_tmp:	ds.b 8
			even
ntc_curx:		dc.b 0				; cursor column (0 based)
ntc_cury:		dc.b 0				; cursor row (0 based)
ntc_scols:		dc.b 40				; columns
ntc_srows:		dc.b 28				; rows
ntc_wrapped:	dc.b 0				; 1 = the last character wrapped to the next line
ntc_tattr:		dc.b $80			; the text cells' attribute (high byte): priority, palette 0
ntc_tbase:		dc.w 0				; added to a character for its tile (Vdp.TextFont: another font)
ntc_ticks:		dc.w 0				; frames since the start
ntc_vbl:		dc.w 0				; frames (ntc_plat_frame waits for it to move)
ntc_pad1:		dc.w 0				; pad 1's buttons now (bit 0 Up ... 7 Start, 8 X ... 11 Mode)
ntc_pad2:		dc.w 0
ntc_padseen:	dc.w 0				; pad 1 as Inkey last saw it (new presses only)
ntc_vhook:		dc.l 0				; a routine the frame interrupt runs (supervisor mode), 0 none
ntc_shadow:		ds.b 40*28			; the console's text
			even
			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_buf		equ ntc_bss + 0		; 10 bytes
pa_dyn		equ ntc_bss + 10		; 12 bytes
pa_names		equ ntc_bss + 22		; 12 bytes
pa_big		equ ntc_bss + 34		; 12 bytes
arr_fixed		equ ntc_bss + 46		; 10 bytes
pa_dyn_data		equ ntc_bss + 56		; 42 bytes
pa_names_data		equ ntc_bss + 98		; 123 bytes
pa_big_data		equ ntc_bss + 222		; 8 bytes
pa_recs_n		equ ntc_bss + 230		; 12 bytes
pa_recs_n_data		equ ntc_bss + 242		; 10 bytes
pa_recs_nm		equ ntc_bss + 252		; 12 bytes
pa_recs_nm_data		equ ntc_bss + 264		; 205 bytes
pa_bytesum_b		equ ntc_bss + 470		; 12 bytes
pa_total_a		equ ntc_bss + 482		; 12 bytes
ntc_bss_size	equ 494
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
